    // Computes the color of the projected texture at the world position "positionWS".
    public virtual float3 ComputeTextureProjectionFromCascade(float3 positionWS, int cascadeIndex, int lightIndex)
    {
        int matrixIndex = cascadeIndex + lightIndex * TCascadeCountBase;

        float4 clipSpaceCoordinate = mul(new float4(positionWS, 1.0f), WorldToProjectiveTextureUV[matrixIndex]);
        float2 projectedTextureCoordinate = clipSpaceCoordinate.xy / clipSpaceCoordinate.w;
        // W-divide because it's a projection matrix.
